+  border-color: color-mix(in oklab, var(--thorp-muted) 50%, transparent);
+}
+
+.pendingHint {
+  position: absolute;
+  top: 50%;
+  right: calc(100% + 10px);
+  z-index: 2;
+  width: max-content;
+  max-width: 260px;
+  padding: 7px 10px;
+  border: 1px solid var(--thorp-line-strong);
+  border-radius: var(--thorp-radius-control, 8px);
+  background: var(--thorp-surface-raised, #1f2321);
+  box-shadow: 0 6px 18px rgb(0 0 0 / 0.28);
+  color: var(--thorp-copy);
+  font-size: var(--thorp-text-small, 0.78rem);
+  line-height: 1.5;
+  opacity: 0;
+  pointer-events: none;
+  transform: translateY(-50%);
+  transition: opacity 0.14s ease;
+  word-break: keep-all;
+}
+
+.orb[data-pending='true']:hover ~ .pendingHint,
+.orb[data-pending='true']:focus-visible ~ .pendingHint {
+  opacity: 1;
+}

